import{Z as t,e as n,f as a,a0 as o}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"Eway","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/payments/eway.md","filePath":"integrations/payments/eway.md","lastUpdated":1780377007000}'),i={name:"integrations/payments/eway.md"};function r(s,e,l,h,c,d){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="eway" tabindex="-1">Eway <a class="header-anchor" href="#eway" aria-label="Permalink to &quot;Eway&quot;">​</a></h1><p>Connect Eway to take payments through the provider configured for your form. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Payments</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Eway</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-eway-api" tabindex="-1">Step 2. Connect to the Eway API <a class="header-anchor" href="#step-2-connect-to-the-eway-api" aria-label="Permalink to &quot;Step 2. Connect to the Eway API&quot;">​</a></h3><ol><li>Log in to the <a href="https://my.eway.io/" target="_blank">Eway Partner Portal</a>.</li><li>Navigate to <strong>My Account</strong> → <strong>API Key</strong>.</li><li>Copy the <strong>API Key</strong> from Eway and paste in the <strong>API Key</strong> field in Formie.</li><li>Copy the <strong>Password</strong> from Eway and paste in the <strong>API Password</strong> field in Formie.</li><li>Copy the <strong>Client Side Encryption Key</strong> from Eway and paste in the <strong>Client Side Encryption Key</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-field-setting" tabindex="-1">Step 4. Field Setting <a class="header-anchor" href="#step-4-field-setting" aria-label="Permalink to &quot;Step 4. Field Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Add a <strong>Payment</strong> field to your form.</li><li>Select Eway for the <strong>Payment Provider</strong>.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Complete a test payment and inspect both the saved submission and the provider’s transaction record. Confirm the amount, currency and final payment state before enabling live payments.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const f=t(i,[["render",r]]);export{p as __pageData,f as default};
